SELECT archivo,
       CASE WHEN bool_and(existe) THEN 'ok' ELSE 'FALTA' END AS pendiente,
       string_agg(CASE WHEN existe THEN NULL ELSE tipo || ' ' || objeto END, ', ') AS que_falta
FROM chequeo
GROUP BY archivo
ORDER BY (bool_and(existe)) ASC, archivo;

